+/** Theoretical (from sales) and actual (all consume movements) use per item between two days (inclusive). */
+export function varianceReport(store, from, to) {
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const theoreticalByItem = new Map();
+  const actualByItem = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = dayOf(m.at);
+    if (day < from || day > to) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    actualByItem.set(itemId, Math.round(((actualByItem.get(itemId) ?? 0) + m.qty) * 1000) / 1000);
+    if (typeof m.ref === "string" && m.ref.startsWith("sale:")) {
+      theoreticalByItem.set(itemId, Math.round(((theoreticalByItem.get(itemId) ?? 0) + m.qty) * 1000) / 1000);
+    }
+  }
+  const itemIds = new Set([...theoreticalByItem.keys(), ...actualByItem.keys()]);
+  return [...itemIds]
+    .map((itemId) => {
+      const theoretical = theoreticalByItem.get(itemId) ?? 0;
+      const actual = actualByItem.get(itemId) ?? 0;
+      return { itemId, theoretical, actual, diff: Math.round((actual - theoretical) * 1000) / 1000 };
+    })
+    .filter((r) => r.theoretical > 0 || r.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
