diff --git a/src/io/sales-import.js b/src/io/sales-import.js
new file mode 100644
index 0000000..f30f011
--- /dev/null
+++ b/src/io/sales-import.js
@@ -0,0 +1,55 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty). Each dish sold
+// consumes one portion of its recipe per qty with ref "sale:<ticket>".
+// Tickets already imported are skipped; any bad row or stock shortage aborts
+// the whole file.
+import { isInstant } from "../dates.js";
+import { consume } from "../domain/batches.js";
+import { scaled } from "../domain/recipes.js";
+import { AppError } from "../errors.js";
+import { parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports sales from CSV; returns { tickets, dishes } or throws naming the row. */
+export function importSales(store, text) {
+  const rows = parseCsvObjects(text);
+  const clean = rows.map((r, i) => {
+    const where = `row ${i + 2}`;
+    for (const k of HEADER) if (!(k in r)) throw new AppError("bad_request", { reason: `${where}: missing column ${k}` });
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    const dish = Number.isInteger(dishId) ? (store.data.dishes ?? []).find((d) => d.id === dishId) : null;
+    if (!dish) throw new AppError("bad_request", { reason: `${where}: unknown dish` });
+    const recipe = store.data.recipes.find((rec) => rec.id === dish.recipeId);
+    if (!recipe) throw new AppError("bad_request", { reason: `${where}: unknown recipe` });
+    const qty = Number(r.qty);
+    if (!Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { where, ticket: r.ticket, soldAt: r.soldAt, recipe, qty };
+  });
+
+  const importedTickets = new Set(
+    store.data.movements.filter((m) => typeof m.ref === "string" && m.ref.startsWith("sale:")).map((m) => m.ref.slice(5)),
+  );
+  const freshRows = clean.filter((r) => !importedTickets.has(r.ticket));
+
+  const snapshot = structuredClone(store.data);
+  for (const r of freshRows) {
+    try {
+      for (const n of scaled(r.recipe, r.qty)) {
+        consume(store, n.itemId, n.qty, { at: r.soldAt, ref: `sale:${r.ticket}` });
+      }
+    } catch (e) {
+      store.data = snapshot;
+      if (e instanceof AppError && e.code === "not_enough_stock") {
+        throw new AppError("not_enough_stock", { ...e.params, item: `${e.params.item} (${r.where})` });
+      }
+      throw e;
+    }
+  }
+
+  return {
+    tickets: new Set(freshRows.map((r) => r.ticket)).size,
+    dishes: freshRows.reduce((sum, r) => sum + r.qty, 0),
+  };
+}
